import process from 'node:process';
import { Buffer } from 'node:buffer';
import { Router } from "npm:express@5.2.1";
import { db, PHOTO_SELECT, tx } from '../db.js';
import { queueApprovalEmail, flushMailQueue } from '../mail.js';
import { photosChanged } from '../events.js';
import { requireAdmin } from '../auth.js';
import { HttpError, shapePhoto, text } from '../util.js';
import { deletePhotoFiles } from './photos.js';
const router = Router();
router.use(requireAdmin);
router.get('/stats', async (_req, res) => {
  const count = async sql => (await db.prepare(sql).get()).n;
  res.json({
    pending: await count("SELECT COUNT(*) AS n FROM photos WHERE status = 'pending'"),
    approved: await count("SELECT COUNT(*) AS n FROM photos WHERE status = 'approved'"),
    rejected: await count("SELECT COUNT(*) AS n FROM photos WHERE status = 'rejected'"),
    users: await count('SELECT COUNT(*) AS n FROM users')
  });
});
router.get('/queue', async (req, res) => {
  const rows = await db.prepare(`${PHOTO_SELECT} WHERE p.status = 'pending' ORDER BY p.created_at ASC, p.id ASC`).all();
  res.json({
    photos: await Promise.all(rows.map(async r => await shapePhoto(r, req.user)))
  });
});
router.get('/photos', async (req, res) => {
  const status = ['approved', 'rejected'].includes(req.query.status) ? req.query.status : 'approved';
  const q = `%${text(req.query.q, {
    max: 80
  })}%`;
  const rows = await db.prepare(`${PHOTO_SELECT}
      WHERE p.status = ? AND (p.title LIKE ? OR p.city LIKE ? OR u.username LIKE ? OR u.display_name LIKE ?)
      ORDER BY p.reviewed_at DESC, p.id DESC LIMIT 120`).all(status, q, q, q, q);
  res.json({
    photos: await Promise.all(rows.map(async r => await shapePhoto(r, req.user)))
  });
});
async function review(req, status, reason = '') {
  const id = Number(req.params.id);
  if (!Number.isSafeInteger(id) || id < 1) throw new HttpError(400, 'Fotografia inválida.');
  const previous = await db.prepare('SELECT status FROM photos WHERE id = ?').get(id);
  const {
    changes
  } = await db.prepare(`UPDATE photos SET status = ?, reject_reason = ?, reviewed_at = datetime('now'), reviewed_by = ?
      WHERE id = ?`).run(status, reason, req.user.id, id);
  if (!changes) throw new HttpError(404, 'Fotografia não encontrada.');
  const photo = await db.prepare(`${PHOTO_SELECT} WHERE p.id = ?`).get(id);
  if (status === 'approved' && previous.status !== 'approved') await queueApprovalEmail(photo);
  return await shapePhoto(photo, req.user);
}
router.post('/photos/:id/approve', async (req, res) => {
  const photo = await tx(async () => await review(req, 'approved'));
  EdgeRuntime.waitUntil(flushMailQueue());
  await photosChanged();
  res.json({
    photo
  });
});
router.post('/photos/:id/reject', async (req, res) => {
  const reason = text(req.body.reason, {
    max: 300,
    label: 'Motivo'
  });
  const photo = await review(req, 'rejected', reason);
  await photosChanged();
  res.json({
    photo
  });
});
router.post('/review-batch', async (req, res) => {
  const {
    ids,
    action
  } = req.body;
  if (!Array.isArray(ids) || !ids.length || ids.length > 100 || ids.some(id => !Number.isSafeInteger(id) || id < 1) || !['approve', 'reject'].includes(action)) throw new HttpError(400, 'Selecção inválida (máximo 100 fotografias).');
  const reason = text(req.body.reason, {
    max: 300,
    label: 'Motivo'
  });
  const unique = [...new Set(ids)];
  await tx(async () => {
    for (const id of unique) {
      const pending = await db.prepare("SELECT id FROM photos WHERE id = ? AND status = 'pending'").get(id);
      if (!pending) throw new HttpError(409, 'A fila foi alterada. Actualiza a selecção.');
      await review({
        params: {
          id
        },
        user: req.user
      }, action === 'approve' ? 'approved' : 'rejected', action === 'reject' ? reason : '');
    }
  });
  EdgeRuntime.waitUntil(flushMailQueue());
  await photosChanged();
  res.json({
    ok: true,
    count: unique.length
  });
});
router.delete('/photos/:id', async (req, res) => {
  const row = await db.prepare('SELECT * FROM photos WHERE id = ?').get(Number(req.params.id));
  if (!row) throw new HttpError(404, 'Fotografia não encontrada.');
  await db.prepare('DELETE FROM photos WHERE id = ?').run(row.id);
  await deletePhotoFiles(row);
  await photosChanged();
  res.json({
    ok: true
  });
});
router.get('/featured', async (req, res) => {
  const rows = await db.prepare(`SELECT f.id AS featured_id, f.note, f.featured_at, p.id AS photo_id
      FROM featured f JOIN photos p ON p.id = f.photo_id ORDER BY f.featured_at DESC, f.id DESC LIMIT 12`).all();
  res.json({
    history: await Promise.all(rows.map(async f => ({
      id: f.featured_id,
      note: f.note,
      featuredAt: f.featured_at,
      photo: await shapePhoto(await db.prepare(`${PHOTO_SELECT} WHERE p.id = ?`).get(f.photo_id), req.user)
    })))
  });
});
router.post('/featured', async (req, res) => {
  const photo = await db.prepare("SELECT id FROM photos WHERE id = ? AND status = 'approved'").get(Number(req.body.photoId));
  if (!photo) throw new HttpError(400, 'Só fotografias aprovadas podem ser Foto da Semana.');
  const note = text(req.body.note, {
    max: 280,
    label: 'Nota'
  });
  await db.prepare('INSERT INTO featured (photo_id, note, featured_by) VALUES (?, ?, ?)').run(photo.id, note, req.user.id);
  await photosChanged();
  res.status(201).json({
    ok: true
  });
});
export default router;
